import{_ as t,o as l,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS G/H (Day 1) - MON: dispatch messages while waiting for IO to complete","description":"","frontmatter":{"title":"CDS G/H (Day 1) - MON: dispatch messages while waiting for IO to complete","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-25T00:00:00.000Z","tags":["Ceph","Monitor","I/O操作","异步化","Paxos","Work Queue"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_MON_-_dispatch_messages_while_waiting_for_IO_to_complete.md","filePath":"posts/2014/CDS_G_H_Day_1_-_MON_-_dispatch_messages_while_waiting_for_IO_to_complete.md","lastUpdated":1780459816000}'),_={name:"posts/2014/CDS_G_H_Day_1_-_MON_-_dispatch_messages_while_waiting_for_IO_to_complete.md"};function s(a,i,r,p,n,g){return l(),e("div",null,[...i[0]||(i[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2014-06-24</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph Monitor消息派发及I/O操作优化</p><p><strong>会议内容</strong>：</p><p><strong>1. 问题背景</strong></p><ul><li>Ceph Monitor在执行I/O操作时，处理消息的能力受限，导致等待时间长，影响整体性能。</li><li>主要问题在于单线程处理所有消息，当执行I/O操作时，其他消息处理被阻塞。</li></ul><p><strong>2. 解决方案</strong></p><ul><li>提出为Monitor添加新的Paxos节点，将控制权交给另一个线程，在等待I/O操作完成期间继续执行其他任务。</li><li>将I/O操作异步化，避免阻塞消息处理。</li><li>考虑使用读写锁机制，保护对状态信息的访问。</li></ul><p><strong>3. 实施步骤</strong></p><ul><li>异步化I/O操作，将任务提交给Key-Value存储，并等待回调。</li><li>使用Work Queue类创建工作线程，将事务指针传递给工作线程。</li><li>在安全的地方异步执行工作，并在完成后进行清理。</li><li>使用Work Queue的flush方法，等待异步操作完成。</li></ul><p><strong>4. 注意事项</strong></p><ul><li>确保异步操作在安全点进行，避免影响其他事件。</li><li>保持读写操作分离，确保持久化数据不会阻塞临时数据。</li><li>考虑将存储源分为已提交和未提交两部分，提高性能。</li></ul><p><strong>5. 后续行动计划</strong></p><ul><li>完成异步化I/O操作的代码实现。</li><li>测试新方案，评估性能提升效果。</li><li>根据测试结果，进一步优化方案。</li></ul><p><strong>关键词</strong></p><ul><li>Monitor</li><li>消息派发</li><li>I/O操作</li><li>异步化</li><li>Paxos</li><li>读写锁</li><li>Work Queue</li><li>Key-Value存储</li></ul>',17)])])}const d=t(_,[["render",s]]);export{c as __pageData,d as default};
